/// Dev-only seed reducer — populates the local SpacetimeDB with realistic mock data.
///
/// # Usage
/// ```bash
/// spacetime call lumiere-v1 seed_dev_data '{}'
/// ```
///
/// Idempotent: exits immediately if "Lumiere Demo Corp" org already exists.
/// Safe to re-run after `spacetime publish --clear-database`.
